insert into public.sample_docs (path, collection, data) values ('templates/tpl-salary_certificate', 'templates', $j${"key": "salary_certificate", "name": "Salary certificate", "category": "employee", "table": "none", "subject": "Salary certificate for {{employee.name}}", "body": "To whom it may concern\n\nThis is to certify that {{employee.name}}, holder of employee number {{employee.number}}, has been employed by {{company.name}} as {{employee.position}} since {{employee.join_date}}.\n\n{{employee.name}} receives a monthly gross salary of {{currency}} {{employee.gross}}, made up of a basic salary of {{currency}} {{employee.basic}}, housing allowance of {{currency}} {{employee.housing}}, transport allowance of {{currency}} {{employee.transport}} and other allowances of {{currency}} {{employee.other}}.\n\nThis certificate is issued at the employee's request for {{purpose}}, without any liability on the part of the company.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-salary_transfer', 'templates', $j${"key": "salary_transfer", "name": "Salary transfer letter", "category": "bank", "table": "none", "subject": "Salary transfer letter for {{employee.name}}", "body": "The Manager\n{{employee.bank}}\n\nDear Sir or Madam,\n\nWe confirm that {{employee.name}} (employee number {{employee.number}}) is employed by {{company.name}} as {{employee.position}} since {{employee.join_date}}, with a monthly gross salary of {{currency}} {{employee.gross}}.\n\nWe undertake to transfer the employee's monthly salary and, on termination, the end-of-service benefits to account {{employee.iban}} held with you, until we receive a clearance letter from the bank.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-employment_letter', 'templates', $j${"key": "employment_letter", "name": "Employment letter", "category": "employee", "table": "none", "subject": "Employment letter for {{employee.name}}", "body": "To whom it may concern\n\nThis is to confirm that {{employee.name}} has been working with {{company.name}} as {{employee.position}} in the {{employee.department}} department since {{employee.join_date}}, a period of {{employee.service_years}} years.\n\nThis letter is issued at the employee's request.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-payslip', 'templates', $j${"key": "payslip", "name": "Payslip", "category": "employee", "table": "payslip", "subject": "Payslip for {{payslip.month}}", "body": "Payslip for {{payslip.month}}\n\nEmployee: {{employee.name}} ({{employee.number}})\nPosition: {{employee.position}}\n\nNet pay of {{currency}} {{payslip.net}} has been transferred to {{employee.iban}}.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-bank_transfer', 'templates', $j${"key": "bank_transfer", "name": "Bank transfer instruction", "category": "bank", "table": "none", "subject": "Transfer instruction, reference {{reference}}", "body": "The Manager\n{{bank_name}}\n\nDear Sir or Madam,\n\nPlease debit our account number {{debit_account}} and transfer {{currency}} {{amount}} ({{amount_words}}) to:\n\nBeneficiary: {{beneficiary}}\nBank: {{beneficiary_bank}}\nIBAN: {{beneficiary_iban}}\nPurpose: {{purpose}}\n\nPlease treat this instruction as authorised by the signatories below.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-customer_balance', 'templates', $j${"key": "customer_balance", "name": "Customer balance confirmation", "category": "customer", "table": "statement", "subject": "Balance confirmation as of {{customer.as_of}}", "body": "Dear {{customer.name}},\n\nOur records show a balance of {{currency}} {{customer.balance}} due from you as of {{customer.as_of}}. The open items are listed below.\n\nPlease confirm the balance, or tell us about any difference, within 15 days. You can also confirm or raise a concern directly from your customer dashboard.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-payment_reminder', 'templates', $j${"key": "payment_reminder", "name": "Payment reminder", "category": "customer", "table": "statement", "subject": "Payment reminder: {{currency}} {{customer.overdue}} overdue", "body": "Dear {{customer.name}},\n\nOur records show {{currency}} {{customer.overdue}} past its due date, out of a total balance of {{currency}} {{customer.balance}}. The items are listed below.\n\nWe would appreciate payment within seven days. If you have already paid, please send us the remittance details.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-supplier_balance', 'templates', $j${"key": "supplier_balance", "name": "Supplier balance confirmation", "category": "supplier", "table": "statement", "subject": "Balance confirmation as of {{supplier.as_of}}", "body": "Dear {{supplier.name}},\n\nOur records show a balance of {{currency}} {{supplier.balance}} owed to you as of {{supplier.as_of}}. The open items are listed below.\n\nPlease confirm that this agrees with your records, or tell us about any difference, within 15 days.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
insert into public.sample_docs (path, collection, data) values ('templates/tpl-noc', 'templates', $j${"key": "noc", "name": "No-objection letter", "category": "employee", "table": "none", "subject": "No-objection letter for {{employee.name}}", "body": "To whom it may concern\n\n{{company.name}} has no objection to {{employee.name}}, our {{employee.position}}, {{purpose}}.\n\nThis letter does not create any financial obligation for the company.", "created_by": "agent:seed", "created_at": "2026-10-13T08:00:00Z"}$j$::jsonb) on conflict (path) do nothing;
